def skill():
    t, k = symbols('t k')
    h = expand(-2*t**3 + 6*t**2)
    crit = solve(diff(h, t), t)
    return sum(h.subs(t, c) for c in crit)

def standard():
    t, k, x = symbols('t k x')
    f = x**3 - 6*x**2 + 9*x
    tan = diff(f, x).subs(x, t)*(0 - t) + f.subs(x, t)
    p = expand(tan - k)
    ks = solve(discriminant(p, t), k)
    ks = [v for v in ks if v.is_real]
    # 서로 다른 실근이 정확히 2개인지 전수 확인
    for v in ks:
        assert len(set(real_roots(Poly(p.subs(k, v), t)))) == 2
    return sum(ks)

def unique():
    return [standard()]
